subscribe\"\n- searchMail \"This week\"\n\nDo these in one block."}],"createdAt":1795321980543},{"type":"tool-invocation","toolInvocation":{"state":"result","result":{"results":[{"name":"setLabels","description":"Set the same label on several emails in a specific mailbox at once. The label must be an existing key from listLabels. Returns each email''s previou...","score":15.59},{"name":"listLabels","description":"List every label key available in this workspace: the built-in labels plus custom labels. Use these exact keys with setLabel.","score":15.46},{"name":"updateLabel","description":"Rename or recolor a custom label in a specific mailbox. Its key stays the same, so labelled emails and workflows keep it.","score":13.13},{"name":"setLabel","description":"Set or change an email''s label in a specific mailbox. The label must be an existing built-in or custom label key — never invent keys.","score":13.03},{"name":"clearLabel","description":"Remove the label from an email in a specific mailbox.","score":11.41}],"loaded":["setLabels","listLabels","updateLabel","setLabel","clearLabel"],"message":"Found and loaded 5 tool(s): setLabels, listLabels, updateLabel, setLabel, clearLabel. They are available on your next turn — call them directly. Some were already loaded."},"toolCallId":"call_3fd18edfad4e4d32a5008e58","toolName":"search_tools","args":{"query":"list emails with a label filter by label"}},"updatedAt":1795321982628},{"type":"tool-invocation","toolInvocation":{"state":"result","result":{"count":56,"emails":[{"mailboxId":"2509b3b7-2ea9-5861-9415-92dd8cc89134","mailbox":"ana@demo.trymetis.email","id":"WyJJTkJPWCIsIjEwMDAiLDQxMF0","threadId":"<1yyu9x3zlnnu3ni6@kestrelsupply.com>","from":"Kestrel Supply Co.","subject":"This week at the shop","date":"Sat Sep 26 2026 08:00:00 GMT+0000 (Coordinated Universal Time)","isRead":true,"isStarred":false,"snippet":""},{"mailboxId":"2509b3b7-2ea9-5861-9415-92dd8cc89134","mailbox":"ana@demo.trymetis.email","id":"WyJJTkJPWCIsIjEwMD