  "mcpServerId" TEXT NOT NULL,
  "versionNumber" INTEGER NOT NULL,
  "name" TEXT NOT NULL,
  "version" TEXT NOT NULL,
  "description" TEXT,
  "instructions" TEXT,
  "repository" TEXT,
  "releaseDate" TEXT,
  "isLatest" INTEGER,
  "packageCanonical" TEXT,
  "tools" TEXT,
  "agents" TEXT,
  "workflows" TEXT,
  "changedFields" TEXT,
  "changeMessage" TEXT,
  "createdAt" TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS mastra_workspaces (
  "id" TEXT NOT NULL PRIMARY KEY,
  "status" TEXT NOT NULL,
  "activeVersionId" TEXT,
  "authorId" TEXT,
  "metadata" TEXT,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS mastra_workspace_versions (
  "id" TEXT NOT NULL PRIMARY KEY,
  "workspaceId" TEXT NOT NULL,
  "versionNumber" INTEGER NOT NULL,
  "name" TEXT NOT NULL,
  "description" TEXT,
  "filesystem" TEXT,
  "sandbox" TEXT,
  "mounts" TEXT,
  "search" TEXT,
  "skills" TEXT,
  "tools" TEXT,
  "autoSync" INTEGER,
  "operationTimeout" INTEGER,
  "changedFields" TEXT,
  "changeMessage" TEXT,
  "createdAt" TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS mastra_skills (
  "id" TEXT NOT NULL PRIMARY KEY,
  "status" TEXT NOT NULL,
  "activeVersionId" TEXT,
  "authorId" TEXT,
  "visibility" TEXT,
  "favoriteCount" INTEGER,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS mastra_skill_versions (
  "id" TEXT NOT NULL PRIMARY KEY,
  "skillId" TEXT NOT NULL,
  "versionNumber" INTEGER NOT NULL,
  "name" TEXT NOT NULL,
  "description" TEXT NOT NULL,
  "instructions" TEXT NOT NULL,
  "license" TEXT,
  "compatibility" TEXT,
  "source" TEXT,
  "references" TEXT,
  "scripts" TEXT,
  "assets" TEXT,
  "files" TEXT,
  "metadata" TEXT,
  "tree" TEXT,
  "changedFields" TEXT,
  "changeMessage" TEXT,
  "createdAt" TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS mastra_favorites (
  "userId" TEXT NOT NULL,
  "entityType" TEXT NOT NULL,
  "entityId" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL,
  PRIMARY KEY ("userId", "entityType", "entityId")
);
CREATE TABLE IF NOT EXISTS mastra_skill_blobs (
  "hash" TEXT NOT NULL PRIMARY KEY,
  "content" TEXT NOT NULL,
  "size" INTEGER NOT NULL,
  "mimeType" TEXT,
  "createdAt" TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS mastra_background_tasks (
  "id" TEXT NOT NULL PRIMARY KEY,
  "tool_call_id" TEXT NOT NULL,
  "tool_name" TEXT NOT NULL,
  "agent_id" TEXT NOT NULL,
  "run_id" TEXT NOT NULL,
  "thread_id" TEXT,
  "resource_id" TEXT,
  "status" TEXT NOT NULL,
  "args" TEXT NOT NULL,
  "result" TEXT,
  "error" TEXT,
  "suspend_payload" TEXT,
  "retry_count" INTEGER NOT NULL,
  "max_retries" INTEGER NOT NULL,
  "timeout_ms" INTEGER NOT NULL,
  "createdAt" TEXT NOT NULL,
  "startedAt" TEXT,
  "suspendedAt" TEXT,
  "completedAt" TEXT,
  "ownerId" TEXT,
  "leaseExpiresAt" TEXT
);
CREATE TABLE IF NOT EXISTS mastra_schedules (
  "id" TEXT NOT NULL PRIMARY KEY,
  "target" TEXT NOT NULL,
  "cron" TEXT NOT NULL,
  "timezone" TEXT,
  "status" TEXT NOT NULL,
  "next_fire_at" INTEGER NOT NULL,
  "last_fire_at" INTEGER,
  "last_run_id" TEXT,
  "created_at" INTEGER NOT NULL,
  "updated_at" INTEGER NOT NULL,
  "metadata" TEXT,
  "owner_type" TEXT,
  "owner_id" TEXT
);
CREATE TABLE IF NOT EXISTS mastra_schedule_triggers (
  "id" TEXT NOT NULL PRIMARY KEY,
  "schedule_id" TEXT NOT NULL,
  "run_id" TEXT,
  "scheduled_fire_at" INTEGER NOT NULL,
  "actual_fire_at" INTEGER NOT NULL,
  "outcome" TEXT NOT NULL,
  "error" TEXT,
  "trigger_kind" TEXT NOT NULL,
  "parent_trigger_id" TEXT,
  "metadata" TEXT
);
CREATE TABLE IF NOT EXISTS mastra_harness_sessions (
  "id" TEXT NOT NULL PRIMARY KEY,
  "ownerId" TEXT NOT NULL,
  "resourceId" TEXT NOT NULL,
  "threadId" TEXT NOT NULL,
  "parentSessionId" TEXT,
  "subagentDepth" INTEGER,
  "source" TEXT,
  "origin" TEXT NOT NULL,
  "runtimeCompatibilityGeneration" TEXT,
  "modeId" TEXT NOT NULL,
  "modelId" TEXT NOT NULL,
  "title" TEXT,
  "metadata" TEXT,
  "state" TEXT,
  "pending" TEXT,
  "createdAt" TEXT NOT NULL,
  "lastActivityAt" TEXT NOT NULL,
  "closingAt" TEXT,
  "closeDeadlineAt" TEXT,
  "closedAt" TEXT,
  "deletedAt" TEXT
);
CREATE TABLE IF NOT EXISTS mastra_tool_provider_connections (
  "authorId" TEXT NOT NULL,
  "providerId" TEXT NOT NULL,
  "connectionId" TEXT NOT NULL,
  "toolkit" TEXT NOT NULL,
  "label" TEXT,
  "scope" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  PRIMARY KEY ("authorId", "providerId", "connectionId")
);
CREATE TABLE IF NOT EXISTS mastra_notifications (
  "id" TEXT NOT NULL,
  "threadId" TEXT NOT NULL,
  "source" TEXT NOT NULL,
  "kind" TEXT NOT NULL,
  "priority" TEXT NOT NULL,
  "status" TEXT NOT NULL,
  "summary" TEXT NOT NULL,
  "payload" TEXT,
  "resourceId" TEXT,
  "agentId" TEXT,
  "sourceId" TEXT,
  "dedupeKey" TEXT,
  "coalesceKey" TEXT,
  "coalescedCount" INTEGER NOT NULL,
  "attributes" TEXT,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  "deliveredAt" TEXT,
  "seenAt" TEXT,
  "dismissedAt" TEXT,
  "archivedAt" TEXT,
  "discardedAt" TEXT,
  "deliverAt" TEXT,
  "summaryAt" TEXT,
  "deliveryReason" TEXT,
  "deliveryAttempts" INTEGER NOT NULL,
  "lastDeliveryAttemptAt" TEXT,
  "lastDeliveryError" TEXT,
  "deliveredSignalId" TEXT,
  "summarySignalId" TEXT,
  "metadata" TEXT,
  PRIMARY KEY ("threadId", "id")
);
CREATE TABLE IF NOT EXISTS mastra_thread_state (
  "threadId" TEXT NOT NULL,
  "type" TEXT NOT NULL,
  "value" TEXT NOT NULL,
  "createdAt" TEXT NOT NULL,
  "updatedAt" TEXT NOT NULL,
  PRIMARY KEY ("threadId", "type")
);
